use crate::packet::{Context,Cover};use hec_native_ic::{fp::Fp,poly::Poly};
pub fn verify(expected:&Context,p:&Cover)->bool{let a=&p.context;let c=&expected.c;if a.c.fp.p!=c.fp.p||a.c.g!=c.g||a.c.f!=c.f||a.d!=expected.d||a.target!=expected.target||a.ell!=expected.ell||a.sm!=expected.sm{return false}let ell=match(c.fp.p,c.f.c[0]){(101,2)=>7481,(251,18)=>67931,(601,7)=>411491,_=>return false};if expected.ell!=ell||c.g!=2||c.f!=Poly::from_coeffs(&[c.f.c[0],0,0,0,0,1])||expected.sm==0||expected.sm>=ell||p.k>=ell||p.z>=c.fp.p||p.z<=1||c.fp.pow(p.z,5)!=1||p.branches.len()!=4||p.reps.len()<2||p.primitives.is_empty(){return false}if !c.is_valid(&a.d)||!c.is_valid(&a.target)||c.is_zero(&a.d){return false}for &(x,y)in &p.reps{if x>=c.fp.p||y>=c.fp.p||c.fp.mul(y,y)!=c.f.eval(x,&c.fp){return false}}if c.mul(&c.place(p.reps[0].0,p.reps[0].1),a.sm)!=a.d{return false}
let f=Fp::new(ell);let mut roots=std::collections::BTreeSet::new();let mut product=Poly::one();for(r,_)in &p.branches{if *r>=ell||!roots.insert(*r){return false}product=product.mul(&Poly::x_minus(*r,&f),&f);}if product!=Poly::from_coeffs(&[1;5]){return false}
let mut phases=std::collections::BTreeMap::new();for(j,&(x,y))in p.reps.iter().enumerate(){let mut xx=x;for e in 0..5{if phases.insert((xx,y),(j,e,false)).is_some(){return false}let ny=c.fp.neg(y);if ny!=y&&phases.insert((xx,ny),(j,e,true)).is_some(){return false}xx=c.fp.mul(xx,p.z);}}
let maxa=p.primitives.iter().map(|x|x.a).max().unwrap();if maxa>16{return false}if p.anchor_certificates.len()!=maxa as usize{return false}let mut anchors=vec![a.target];for proof in &p.anchor_certificates{if !crate::certificate::verify(c,anchors.last().unwrap(),&a.d,proof){return false}anchors.push(proof.out);}for prim in &p.primitives{if prim.a==0||prim.t>=c.fp.p||(!crate::geometry::roots(c,&anchors[prim.a as usize],prim.t,&prim.points)&&!crate::geometry::exact(c,&anchors[prim.a as usize],prim.t,&prim.points)){return false}}
for prim in &p.primitives{if prim.points.iter().any(|xy|!phases.contains_key(xy)){return false}}let n=p.reps.len()+1;let mut anyscalar=false;for(r,proof)in &p.branches{if proof.w.len()!=p.primitives.len()+1||proof.w.iter().any(|w|*w>=ell)||proof.k>=ell||(!proof.excluded&&proof.k!=p.k)||(proof.excluded&&proof.k!=1){return false}let mut powers=[1;5];for j in 1..5{powers[j]=f.mul(powers[j-1],*r);}let mut acc=vec![0;n];acc[0]=proof.w[0];let mut rhs=f.mul(proof.w[0],f.inv(a.sm));for(i,prim)in p.primitives.iter().enumerate(){let w=proof.w[i+1];if w==0{continue}acc[n-1]=f.add(acc[n-1],w);rhs=f.sub(rhs,f.mul(w,prim.a));for xy in &prim.points{let Some(&(j,e,neg))=phases.get(xy)else{return false};let mut coefficient=powers[e];if neg{coefficient=f.neg(coefficient)}acc[j]=f.add(acc[j],f.mul(w,coefficient));}}let mut want=vec![0;n];let want_rhs=if proof.excluded{1}else{anyscalar=true;want[n-1]=1;p.k};if acc!=want||rhs!=want_rhs{return false}}anyscalar}
